// Test network access to the PlantUML server with a tiny diagram
const puml = "@startuml\nBob -> Alice : hello\n@enduml";
const stdAlphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const pumlAlphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_';
function plantUmlEncode(text) {
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  const std = btoa(bin).replace(/=+$/, '');
  let out = '';
  for (const ch of std) out += pumlAlphabet[stdAlphabet.indexOf(ch)];
  return out;
}
const enc = plantUmlEncode(puml);
const url = `https://www.plantuml.com/plantuml/png/${enc}`;
try {
  const res = await fetch(url);
  const buf = new Uint8Array(await res.arrayBuffer());
  return { status: res.status, contentType: res.headers.get('content-type'), bytes: buf.length, head: Array.from(buf.slice(0, 8)) };
} catch (e) {
  return { error: String(e) };
}

